const raw = $input.first().json;
const resp = typeof raw === 'string' ? JSON.parse(raw) : raw;
const msg = resp && resp.choices && resp.choices[0] && resp.choices[0].message;
const text = (msg && typeof msg.content === 'string' && msg.content.trim()) ? msg.content : (msg && typeof msg.reasoning_content === 'string' ? msg.reasoning_content : '');
const t = String(text).replace(/```json/g, '').replace(/```/g, '').trim();
let plan = null;
try { plan = JSON.parse(t); } catch { const m = t.match(/\{[\s\S]*\}/); if (m) { try { plan = JSON.parse(m[0]); } catch {} } }
if (!plan) { const ctx0 = JSON.parse(($('读上下文').first().json.stdout || '{}')); return [{ json: { payload_b64: Buffer.from(JSON.stringify({ book_id: (ctx0.context && ctx0.context.book_id) || '', blueprint_updates: [], reader_persona: null, volume_goal: '' })).toString('base64') } }]; }
const ctx = JSON.parse($('读上下文').first().json.stdout || '{}');
const payload = { book_id: (ctx.context && ctx.context.book_id) || '', blueprint_updates: plan.blueprint_updates || [], reader_persona: plan.reader_persona || null, volume_goal: plan.volume_goal_adjust || '' };
return [{ json: { payload_b64: Buffer.from(JSON.stringify(payload)).toString('base64') } }];
